out={'schema':'marici.conjecture-replay.current-interface-centrality.v1','target':'physical_valg_channel','method':'Shapley allocation of downstream action unlocks plus target reachability across complementary candidate interfaces','candidate_interfaces':{x:{'producer':{'exact_overlap_comparison':'VC2f','support_boundary_admissible':'VC2g','reconstruction_feasibility':'VC2h'}[x],'cost':costs[x],'coalitional_unlock_value':shapley[x],'value_per_cost':shapley[x]/costs[x]} for x in costs},'ranking':ranked,'recommendation':{'interface':ranked[0],'action':{'exact_overlap_comparison':'VC2f','support_boundary_admissible':'VC2g','reconstruction_feasibility':'VC2h'}[ranked[0]]},'interpretation':'Exact reconstruction and support descent are complementary bottleneck interfaces. Support audit ranks first because it receives equal coalitional centrality at lower cost; the optional feasibility scout has zero dependency centrality.','passed':ranked[0]=='support_boundary_admissible'};assert out['passed'];(R/'research/conjecture_replay/results/current_interface_centrality.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'shapley':shapley,'ranking':ranked,'recommendation':out['recommendation']}))
